module.exports = "const REC = {\n  prof: { label:'Professeur', f:4, level:'Formel', register:'Vouvoiement', length:'5 à 10 lignes',\n    note:\"Ton prof reçoit beaucoup de mails. Présente-toi (nom + classe) dès la première ligne et va droit au but.\",\n    greet:'Bonjour Madame Dupont, / Bonjour Monsieur Martin,', polite:'Je vous remercie par avance. Bien cordialement,',\n    yes:'Nom et classe, une demande précise, une date.', no:'« Salut », « Coucou prof », un mail sans signature.',\n    scenario:\"Tu as été malade trois jours. Demande à ta prof de français, Mme Dupont (s.dupont@institut-stmichel.be), un délai pour ton exposé.\" },\n  recruteur: { label:'Recruteur', f:5, level:'Très formel', register:'Vouvoiement', length:'8 à 12 lignes + CV en pièce jointe',\n    note:\"C'est ta première impression. Zéro faute, un objet qui cite le poste, et ton CV en pièce jointe nommé proprement.\",\n    greet:'Madame, Monsieur, / Madame Leroy,', polite:\"Je vous prie d'agréer, Madame, Monsieur, l'expression de mes salutations distinguées.\",\n    yes:'Poste visé, tes disponibilités, une phrase de motivation.', no:'Une adresse perso fantaisiste (dark-gamer99@…), un mail vide avec juste le CV.',\n    scenario:\"Envoie ta candidature pour un job étudiant d'été à la librairie Page 7 (jobs@librairie-page7.be). Ton CV est en pièce jointe.\" },\n  sup: { label:'Supérieur', f:4, level:'Formel', register:'Vouvoiement', length:'4 à 8 lignes',\n    note:\"En stage ou au travail : sois clair sur ce que tu demandes et pour quand. Propose une solution si ta demande crée un souci.\",\n    greet:'Bonjour Madame Lambert,', polite:'Merci pour votre retour. Bien cordialement,',\n    yes:'Dates exactes, raison courte, proposition pour rattraper.', no:'Te justifier sur dix lignes, oublier de préciser la date.',\n    scenario:\"Tu es en stage. Demande à ta tutrice, Mme Lambert (c.lambert@atelier-numerique.be), de partir plus tôt vendredi pour un examen.\" },\n  collegue: { label:'Collègue / camarade', f:2, level:'Détendu', register:'Tutoiement possible', length:'2 à 5 lignes',\n    note:\"Plus simple, mais toujours clair : une demande, une échéance. Le tutoiement est ok si vous vous tutoyez déjà.\",\n    greet:'Bonjour Julien, / Salut Julien,', polite:'Merci ! Bonne journée,',\n    yes:'Une échéance, un lien vers le document partagé.', no:\"Écrire tout le mail dans l'objet, ou mettre toute la classe en copie.\",\n    scenario:\"Projet de groupe : demande à Julien (julien.renson@eleves-stmichel.be) de t'envoyer sa partie avant jeudi.\" },\n  client: { label:'Client', f:4, level:'Formel', register:'Vouvoiement', length:'4 à 8 lignes',\n    note:\"Rappelle de quoi on parle (commande, date, montant) : ton client ne doit pas avoir à chercher.\",\n    greet:'Bonjour Monsieur Renard,', polite:'Nous restons à votre disposition. Cordialement,',\n    yes:\"Récapituler la commande, l'heure et le lieu.\", no:'Un ton familier, des abréviations (« cmd », « rdv »).',\n    scenario:\"Tu gères la vente de gâteaux de l'école. Confirme à M. Renard (p.renard@mail.be) sa commande de 3 tartes pour samedi.\" },\n  admin: { label:'Administration', f:5, level:'Très formel', register:'Vouvoiement', length:'5 à 8 lignes',\n    note:\"Donne toutes les infos d'identification (nom, date de naissance, adresse) : ça évite un aller-retour.\",\n    greet:'Madame, Monsieur,', polite:\"Veuillez agréer, Madame, Monsieur, mes salutations distinguées.\",\n    yes:'Tes coordonnées complètes, le document exact demandé.', no:\"« Bonjour à vous », une demande vague (« j'ai besoin d'un papier »).\",\n    scenario:\"Demande au service population de ta commune (population@commune-exemple.be) une attestation de domicile.\" },\n  ami: { label:'Ami / famille', f:1, level:'Familier', register:'Tutoiement', length:'Libre',\n    note:\"Tu peux être toi-même. Garde quand même un objet et une info claire (date, lieu) pour une invitation.\",\n    greet:'Coucou Inès ! / Salut Tom,', polite:'Bisous, / À samedi !',\n    yes:\"Date, heure, lieu, et ce qu'il faut apporter.\", no:\"Oublier l'essentiel : quand et où.\",\n    scenario:\"Invite ta cousine Inès (ines.martin@mail.be) à ton anniversaire samedi prochain.\" }\n  ,\n  dir: { fun:true, emoji:'🎮', label:'Club jeux vidéo', f:4, level:'Formel', register:'Vouvoiement', length:'6 à 10 lignes',\n    note:\"Convaincre un directeur, c'est présenter un projet sérieux : qui tu es, ce que tu proposes, et un rendez-vous à demander.\",\n    greet:'Bonjour Monsieur Vandenberg,', polite:'Je vous remercie par avance pour votre attention. Bien cordialement,',\n    yes:'Un projet clair, une proposition de rendez-vous.', no:'Un ton copain, « on veut un club ! » sans explication.',\n    scenario:\"Propose au directeur, M. Vandenberg (direction@institut-stmichel.be), de créer un club de jeux vidéo à l'école le mercredi midi.\" },\n  parent: { fun:true, emoji:'🐱', label:'Un chaton ?', f:1, level:'Familier', register:'Tutoiement', length:'4 à 8 lignes',\n    note:\"Avec ta famille, tu peux rester naturel. Mais pour convaincre, donne des arguments et des promesses concrètes.\",\n    greet:'Coucou maman !', polite:'Merci beaucoup, bisous,',\n    yes:'Un ou deux arguments, une promesse précise.', no:'Juste « je veux un chat » sans rien proposer.',\n    scenario:\"Convaincs ta maman (maman@famille-martin.be) de te laisser adopter un chaton. Sois convaincant·e !\" },\n  sav: { fun:true, emoji:'📦', label:'Colis perdu', f:5, level:'Très formel', register:'Vouvoiement', length:'6 à 10 lignes',\n    note:\"Une réclamation efficace donne le numéro de commande, les dates, et dit clairement ce que tu attends : remboursement ou nouvel envoi.\",\n    greet:'Madame, Monsieur,', polite:\"Je vous prie d'agréer, Madame, Monsieur, mes salutations distinguées.\",\n    yes:'Numéro de commande, dates, solution demandée.', no:'Insulter le service client, rester vague (« ça marche pas »).',\n    scenario:\"Ton colis (des écouteurs, commande n° 48213) n'est jamais arrivé. Écris au service client de la boutique TechPlanet (service@techplanet.be).\" },\n  club: { fun:true, emoji:'⚽', label:'Club de foot', f:4, level:'Formel', register:'Vouvoiement', length:'5 à 8 lignes',\n    note:\"Un entraîneur reçoit beaucoup de demandes : présente-toi, dis ton âge ou ton niveau, et propose un essai.\",\n    greet:'Bonjour Monsieur Dubois,', polite:'Je vous remercie par avance. Bien cordialement,',\n    yes:'Âge, niveau, proposition d\\'un essai.', no:'« Salut coach » ou une demande sans âge ni disponibilité.',\n    scenario:\"Tu veux t'inscrire au club de foot du quartier. Écris à l'entraîneur, M. Dubois (entrainement@fc-quartier.be), pour demander un entraînement d'essai.\" },\n  stream: { fun:true, emoji:'🎥', label:'Ta streameuse', f:2, level:'Détendu', register:'Tutoiement', length:'4 à 8 lignes',\n    note:\"Avec une créatrice que tu admires, reste poli et enthousiaste, mais précis : ce que tu proposes et pourquoi ça peut l'intéresser.\",\n    greet:'Bonjour Luna,', polite:'Merci beaucoup et bonne continuation,',\n    yes:'Un compliment sincère, un projet concret.', no:'Un message vide du type « salut tu fais quoi ».',\n    scenario:\"Écris à Luna, ta streameuse préférée (contact@luna-stream.be), pour lui demander si elle peut parler du club de jeux vidéo de ton école pendant un live.\" }\n};\nconst KEYS = Object.keys(REC);\nconst CORE = KEYS.filter(k => !REC[k].fun), FUN = KEYS.filter(k => REC[k].fun);\n\n/* Ce que l'analyse attend pour chaque situation (cohérence avec la consigne) */\nconst DATE_RE = /\\d|lundi|mardi|mercredi|jeudi|vendredi|samedi|dimanche|demain|semaine|prochain|avant|jusqu/;\nconst EXPECT = {\n  prof: { email:'s.dupont@institut-stmichel.be', name:'dupont', gender:'f', intro:true, topic:/expos|delai|report|retard|presentation|demande/, topicEx:'exposé, délai',\n    needs:[[DATE_RE,\"Précise une date : pour quand demandes-tu le délai ?\"]] },\n  recruteur: { email:'jobs@librairie-page7.be', name:null, intro:true, bodyTopic:/postul|candidat|job|emploi|etudiant|poste|equipe|rejoindre|recrut|vendeu|librairie|disponib/, topic:/candidature|job|emploi|etudiant|vendeu|poste/, topicEx:'candidature, job étudiant',\n    needs:[[/disponib|juillet|aout|juin|ete|horaire|semaine/,\"Indique tes disponibilités (dates, périodes).\"],[/\\bcv\\b|piece jointe|ci-joint|en annexe|joint/,\"Annonce ton CV en pièce jointe.\"]] },\n  sup: { email:'c.lambert@atelier-numerique.be', name:'lambert', gender:'f', bodyTopic:/depart|partir|absence|examen|vendredi|demande|conge|horaire/, intro:false, topic:/depart|absence|examen|vendredi|demande|conge|horaire/, topicEx:'départ anticipé, examen',\n    needs:[[/vendredi|\\d/,\"Donne le jour (vendredi) et si possible l'heure.\"],[/examen|cours|raison|epreuve/,\"Explique brièvement la raison (ton examen).\"]] },\n  collegue: { email:'julien.renson@eleves-stmichel.be', name:'julien', intro:false, topic:/projet|partie|sciences|jeudi|envoi|envoyer|document/, topicEx:'projet, ta partie',\n    needs:[[/jeudi|avant|echeance|pour le/,\"Rappelle l'échéance (avant jeudi).\"],[/partie|part|texte|section/,\"Précise ce que tu attends (sa partie).\"]] },\n  client: { email:'p.renard@mail.be', name:'renard', gender:'m', intro:false, ask:/confirm|n'hesitez pas|restons a votre disposition|retirer|retrait|vous attend/, askHint:\"Dis clairement ce que tu confirmes et ce qu'il doit faire (venir retirer sa commande).\", topic:/commande|tarte|samedi|confirmation/, topicEx:'commande, tartes',\n    needs:[[/tarte|commande/,\"Rappelle la commande (3 tartes).\"],[/samedi|\\d|heure|retrait|livraison/,\"Donne le jour et l'heure de retrait.\"]] },\n  admin: { email:'population@commune-exemple.be', name:null, intro:true, topic:/attestation|domicile|demande/, topicEx:'attestation de domicile',\n    needs:[[/attestation|domicile/,\"Nomme précisément le document demandé.\"],[/\\d|naissance|ne le|nee|adresse|rue/,\"Ajoute tes coordonnées (date de naissance, adresse).\"]] },\n  ami: { email:'ines.martin@mail.be', name:'ines', intro:false, topic:/anniv|samedi|invitation|fete|soiree/, topicEx:'anniversaire, samedi',\n    needs:[[/samedi|\\d|heure|\\bh\\b/,\"Dis quand (jour et heure).\"],[/chez|lieu|adresse|rue|maison|resto|parc|salle|a la|au /,\"Dis où ça se passe.\"]] }\n\n  ,dir: { email:'direction@institut-stmichel.be', name:'vandenberg', gender:'m', intro:true, topic:/club|jeu|proposition|projet|creation/, topicEx:'club, jeux vidéo',\n    needs:[[/club|jeu/,\"Nomme ton projet (le club de jeux vidéo).\"],[DATE_RE,\"Propose un moment pour en parler (la semaine prochaine, un mercredi…).\"]] },\n  parent: { email:'maman@famille-martin.be', name:'maman', intro:false, topic:/chat|chaton|adopt|demande|idee/, topicEx:'chaton, adopter',\n    needs:[[/chat/,\"Dis clairement ce que tu demandes (adopter un chaton).\"],[/parce que|car |promis|promets|responsab|m'occuper|je m'engage|argent de poche/,\"Donne au moins un argument ou une promesse.\"]] },\n  sav: { email:'service@techplanet.be', name:null, intro:false, topic:/commande|colis|livraison|reclamation|48213/, topicEx:'colis, commande 48213',\n    needs:[[/48213|commande/,\"Rappelle le numéro de commande (48213).\"],[/rembours|renvoi|nouvel envoi|remplac|solution/,\"Dis ce que tu attends (remboursement ou nouvel envoi).\"]] },\n  club: { email:'entrainement@fc-quartier.be', name:'dubois', gender:'m', intro:true, topic:/inscription|club|foot|essai|entrainement/, topicEx:'inscription, essai',\n    needs:[[/\\bans\\b|niveau|debutant|joue|joueur/,\"Dis ton âge ou ton niveau.\"],[DATE_RE,\"Propose un jour pour l'essai (le mercredi, samedi…).\"]] },\n  stream: { email:'contact@luna-stream.be', name:'luna', intro:false, topic:/live|stream|collab|jeu|club|idee|question/, topicEx:'live, club',\n    needs:[[/live|stream|video|chaine/,\"Parle de son live ou de sa chaîne.\"],[/club|ecole|jeu/,\"Explique ton projet (le club de jeux vidéo).\"]] }\n};\nconst ABBR_MAP = { prez:'présentation', pres:'présentation', pb:'problème', dem:'demande', rdv:'rendez-vous', tt:'tout', tjs:'toujours', tjrs:'toujours', bcp:'beaucoup', qq:'quelque', qqch:'quelque chose', pr:'pour', pk:'pourquoi', pq:'pourquoi', pcq:'parce que', pck:'parce que', slt:'salut', bjr:'bonjour', stp:\"s'il te plaît\", svp:\"s'il vous plaît\", mdr:'', lol:'', tkt:\"ne t'inquiète pas\", jsp:'je ne sais pas', wsh:'', dsl:'désolé', mrc:'merci', ctt:'contact', vs:'vous', dispo:'disponible', asap:'dès que possible', pdt:'pendant', msg:'message', info:'information', infos:'informations', ordi:'ordinateur', aprem:'après-midi', appart:'appartement', resto:'restaurant', ado:'adolescent', vac:'vacances', kdo:'cadeau', ptit:'petit', ptite:'petite', cad:\"c'est-à-dire\", ds:'dans', ms:'mais', mm:'même', cc:'bonjour', ct:\"c'était\", ke:'que', ki:'qui', koi:'quoi', kel:'quel', tro:'trop', exo:'exercice', exos:'exercices', maths:'mathématiques', dej:'déjeuner' };\nconst ABBR_SOFT = new Set(['dispo','info','infos','ordi','aprem','appart','resto','ado','vac','kdo','exo','exos','maths','ptit','ptite','tt','pr','ds','dej','msg']);\nconst ABBR = new RegExp(\"\\\\b(\" + Object.keys(ABBR_MAP).join('|') + \")\\\\b\");\nconst ABBR_G = new RegExp(\"\\\\b(\" + Object.keys(ABBR_MAP).join('|') + \")\\\\b\", 'g');\nconst ENGLISH = /\\b(dear|hi|thanks|thank you|please|regards|sincerely|sorry|best wishes|yours|teacher|good morning|good evening|my name|i am|i would|could you|looking forward)\\b/;\nconst FUNC = /\\b(le|la|les|l'|un|une|des|du|de|d'|au|aux|ce|cet|cette|ces|mon|ma|mes|ton|ta|tes|son|sa|ses|notre|nos|votre|vos|leur|leurs|je|j'|tu|il|elle|on|nous|vous|ils|elles|me|m'|te|t'|se|s'|lui|en|que|qu'|qui|et|ou|mais|donc|car|pour|par|avec|sans|dans|sur|sous|chez|avant|apres|depuis|jusqu'|si|ne|n'|pas|plus|tres|tout|tous|toute|comme|quand|c'|ca|cela)\\b/;\nconst AUX = /\\b(suis|es|est|sommes|etes|sont|etais|etait|etions|etiez|etaient|ete|serai|sera|serait|seras|serons|seront|ai|as|a|avons|avez|ont|avais|avait|avions|aviez|avaient|aurai|aura|aurait|fais|fait|faites|font|va|vais|vas|allons|allez|vont|peux|peut|pouvons|pouvez|peuvent|pourrai|pourra|pourrait|pourriez|pourrais|veux|veut|voulons|voulez|veulent|voudrais|voudrait|dois|doit|devons|devez|doivent|devait|dit|dis|dites|sais|sait|savez|viens|vient|venons|venez|viennent|merci|remercie|souhaite|souhaiterais|aimerais|aime|espere|confirme|confirmons|propose|demande|joue|restons|attends|attend)\\b/;\nconst VERBSUF = /\\b[a-z]{3,}(er|ir|ons|ez|ent|ait|ais|ai|erai|era|erait|ront|iez|ant|ee|ees|es|e)\\b/;\nconst INFORMAL = { salut:'bonjour', coucou:'bonjour', hello:'bonjour', hey:'bonjour', ok:\"d'accord\", okay:\"d'accord\", ouais:'oui', nan:'non', bouger:'déplacer', truc:'chose', machin:'chose', bosser:'travailler', taf:'travail', mec:'monsieur', pote:'ami', genre:'par exemple', kiffer:'apprécier', cool:'très bien', 'du coup':'donc', 'ça marche':'cela me convient', 'a plus':'cordialement', 'à plus':'cordialement', bisous:'cordialement', 'je veux':'je souhaiterais', 'faut que':'il faut que' };\n\n\nconst STEPS = [\n  { z:'to', t:'Le destinataire', x:\"Dans « À », tu mets la personne qui doit agir : celle à qui tu poses ta question ou fais ta demande. S'il y a plusieurs personnes concernées, tu peux en mettre plusieurs.\", tip:\"Remplis le champ « À » en dernier : tu évites d'envoyer un brouillon par erreur.\", a:\"Mettre 30 personnes en « À » quand une seule est concernée.\" },\n  { z:'cc', t:'Cc et Cci : qui reçoit une copie', x:\"« Cc » veut dire copie : les personnes qui doivent seulement être au courant. Tout le monde voit leur adresse. « Cci » veut dire copie cachée : la personne reçoit le mail, mais les autres ne voient pas son adresse. On l'utilise pour écrire à un groupe de personnes qui ne se connaissent pas, afin de ne pas partager leurs adresses.\", tip:\"Écris à plusieurs personnes qui ne se connaissent pas ? Mets-les toutes en « Cci ».\", a:\"Mettre toute la classe en « Cc » : tout le monde recevra les réponses si quelqu'un clique sur « Répondre à tous ».\" },\n  { z:'subject', t:\"L'objet\", x:\"Le titre de ton mail. Il doit dire en quelques mots de quoi tu parles, pour que la personne sache si c'est urgent avant même d'ouvrir.\", tip:\"Sujet + action : « Devoir de géo : demande de délai ».\", a:\"Un objet vide, « Question », « Urgent !!! » ou tout ton message dans l'objet.\" },\n  { z:'greet', t:\"La formule d'appel\", x:\"La première ligne, suivie d'une virgule. Elle donne le ton du mail : « Bonjour Madame Dupont, » n'a pas le même effet que « Salut ! ».\", tip:\"Si tu ne connais pas le nom : « Madame, Monsieur, ».\", a:\"« Bonjour Madame Sophie » : jamais le prénom avec Madame ou Monsieur.\" },\n  { z:'intro', t:'La présentation', x:\"Une phrase pour dire qui tu es, si la personne ne te connaît pas bien. Ton prof a peut-être 150 élèves !\", tip:\"Nom + contexte : « élève de 4e B », « stagiaire au service IT ».\", a:\"Commencer directement par la demande sans te présenter.\" },\n  { z:'body', t:'Le contexte', x:\"Explique la situation en 1 à 3 phrases : ce qui s'est passé, les dates, les faits. Un paragraphe = une idée.\", tip:\"Relis-toi : chaque phrase doit être utile à la personne.\", a:\"Raconter toute ta semaine, écrire en un seul bloc sans retour à la ligne.\" },\n  { z:'ask', t:'La demande', x:\"Le cœur du mail : qu'attends-tu de la personne ? Formule-le clairement, avec une date si besoin.\", tip:\"« Serait-il possible de… ? », « Pourriez-vous… ? ».\", a:\"Une demande floue ou cachée au milieu d'un paragraphe.\" },\n  { z:'polite', t:'La formule de politesse', x:\"Tu remercies et tu conclus. Plus la personne est haut placée ou inconnue, plus la formule est soutenue.\", tip:\"« Bien cordialement, » marche dans presque toutes les situations formelles.\", a:\"« Cdlt », « Bizz » ou rien du tout.\" },\n  { z:'sign', t:'La signature', x:\"Ton prénom et ton nom, et si utile ta classe, ton école ou ton numéro. La personne doit savoir qui tu es sans regarder ton adresse.\", tip:\"Crée une signature automatique dans ta messagerie.\", a:\"Signer « Léa » seule dans un mail formel, ou pas de signature.\" },\n  { z:'attach', t:'La pièce jointe', x:\"Un document à envoyer ? Joins-le et annonce-le dans le texte. Donne-lui un nom clair. Attention à la taille : les messageries limitent le poids des pièces jointes, souvent autour de 20 à 25 Mo.\", tip:\"Nomme tes fichiers : « CV-Lea-Martin.pdf ». Préfère le PDF.\", a:\"Écrire « voir PJ » et oublier de la joindre (ça arrive à tout le monde).\" },\n  { z:'prio', t:'La priorité', x:\"Certaines messageries, comme Outlook, permettent de marquer un mail en « importance haute » : le destinataire voit alors un point d'exclamation rouge dans sa boîte de réception. Toutes les messageries n'ont pas ce bouton, et son affichage peut varier selon la messagerie de la personne qui reçoit.\", tip:\"Réserve la priorité haute aux messages vraiment urgents, avec une date précise dans le texte.\", a:\"Tout marquer comme urgent : à force, personne ne le remarque plus, et c'est mal perçu.\" },\n  { z:'draft', t:'Le brouillon', x:\"Un mail pas fini ? Tu peux l'enregistrer en brouillon : il reste dans le dossier « Brouillons » et tu le retrouves plus tard. Beaucoup de messageries le font aussi toutes seules pendant que tu écris. Un mail important mérite d'être relu après une pause, avant de l'envoyer.\", tip:\"Écris, enregistre en brouillon, fais une pause, puis relis-toi à voix haute avant d'envoyer.\", a:\"Envoyer tout de suite, sans relire : une faute ou un oubli ne se rattrape plus.\" },\n  { z:'reply', t:'Répondre, répondre à tous, transférer', x:\"« Répondre » écrit uniquement à la personne qui t'a écrit. « Répondre à tous » écrit aussi à toutes les personnes en copie. « Transférer » envoie le mail à quelqu'un d'autre. Ces trois boutons sont proches : on se trompe vite.\", tip:\"Avant de cliquer sur « Répondre à tous », demande-toi : est-ce que chaque personne a besoin de lire ma réponse ?\", a:\"Répondre à tous pour dire « merci » ou « ok » : tu remplis la boîte de réception de dizaines de personnes. Et vérifie aussi avant de transférer : le mail d'origine contient peut-être des informations privées.\" },\n  { z:'follow', t:'La relance', x:\"Pas de réponse ? Les gens sont occupés et un mail peut se perdre. Attends quelques jours, puis envoie un court rappel poli, dans le même fil, en rappelant ta demande. Pour une candidature, on peut relancer environ 15 jours après l'envoi.\", tip:\"« Je me permets de revenir vers vous au sujet de mon message du 6 octobre. »\", a:\"Relancer le lendemain, ou envoyer plusieurs rappels agacés (« Vous avez vu mon mail ??? »).\" }\n];\n\nconst QCM = {\n  comprendre: [\n    { q:\"Pour éviter d'envoyer un brouillon par erreur, quel champ remplis-tu en dernier ?\", o:[\"L'objet\",\"Le destinataire (« À »)\",\"La signature\"], a:1, why:\"Sans adresse, le mail ne peut pas partir : tu as le temps de te relire.\" },\n    { q:\"Tu écris à ta prof, Mme Dupont. Quelle formule d'appel est la bonne ?\", o:[\"Salut Madame,\",\"Bonjour Madame Sophie,\",\"Bonjour Madame Dupont,\",\"Hello,\"], a:2, why:\"Madame ou Monsieur + nom de famille, jamais le prénom, et une virgule à la fin.\" },\n    { q:\"Quel objet est le plus efficace ?\", o:[\"Question\",\"Urgent !!!\",\"Devoir de géo : demande de délai\",\"Bonjour Madame\"], a:2, why:\"Un bon objet dit de quoi on parle et ce que tu demandes, en quelques mots.\" },\n    { q:\"Tu écris à 20 parents qui ne se connaissent pas. Où mets-tu leurs adresses ?\", o:[\"Toutes en « À »\",\"En « Cci »\",\"En « Cc »\"], a:1, why:\"« Cci » est la copie cachée : chaque parent reçoit le mail sans voir les adresses des autres.\" },\n    { q:\"Tu écris « mon CV est en pièce jointe ». Que fais-tu avant d'envoyer ?\", o:[\"Rien, c'est bon\",\"Je vérifie que le fichier est bien joint\",\"Je le copie dans le texte\"], a:1, why:\"Annoncer une pièce jointe sans la joindre arrive à tout le monde : un dernier coup d'œil évite l'oubli.\" }\n  ],\n  adapter: [\n    { q:\"Pour terminer une candidature, quelle formule de politesse choisis-tu ?\", o:[\"Bizz\",\"À+\",\"Je vous prie d'agréer, Madame, Monsieur, l'expression de mes salutations distinguées.\",\"Merci, bye\"], a:2, why:\"Plus la situation est formelle ou le destinataire inconnu, plus la formule est soutenue.\" },\n    { q:\"Tu invites une amie à ton anniversaire. Qu'est-ce qui reste indispensable ?\", o:[\"Une formule très soutenue\",\"La date, l'heure et le lieu\",\"Un long paragraphe d'introduction\"], a:1, why:\"Même entre amis, le message doit contenir l'essentiel : quand et où.\" },\n    { q:\"Tu écris à ta tutrice de stage. Quel début convient ?\", o:[\"Salut, ça va ?\",\"Bonjour Madame Lambert, je me permets de vous écrire pour…\",\"Yo Madame,\"], a:1, why:\"Tutrice ou supérieur : vouvoiement, nom de famille, ton poli et direct.\" },\n    { q:\"Pour confirmer une commande à un client, que rappelles-tu en premier ?\", o:[\"Ta journée\",\"La commande, la date et le lieu\",\"Un « cmd » abrégé\"], a:1, why:\"Le client ne doit pas avoir à chercher : tu récapitules l'essentiel dès le début.\" }\n  ]\n};\n\n\n/* Banque du quiz final : tire 10 questions au hasard parmi toutes les parties */\nconst BANK_EXTRA = [\n  { part:1, q:\"Tu veux seulement dire « merci » à la personne qui t'a écrit, avec 15 personnes en copie. Que cliques-tu ?\", o:[\"Répondre à tous\",\"Répondre\",\"Transférer\"], a:1, why:\"« Répondre » écrit uniquement à l'expéditeur. « Répondre à tous » dérange inutilement tout le monde.\" },\n  { part:1, q:\"Ta demande est restée sans réponse. Que fais-tu ?\", o:[\"J'attends quelques jours, puis j'envoie un rappel poli\",\"J'envoie dix messages dans l'heure\",\"J'abandonne tout de suite\"], a:0, why:\"Un court rappel poli, dans le même fil, après quelques jours, fait ressortir ta demande sans agacer.\" },\n  { part:1, q:\"Quand marques-tu un mail en « importance haute » ?\", o:[\"Pour tous mes mails\",\"Seulement quand c'est vraiment urgent\",\"Jamais, c'est interdit\"], a:1, why:\"Si tout est urgent, plus rien ne l'est. Réserve cette option aux messages qui le méritent.\" },\n  { part:1, q:\"Ton mail n'est pas fini. Que fais-tu ?\", o:[\"Je l'envoie quand même\",\"Je l'enregistre en brouillon et je le termine plus tard\",\"Je le supprime\"], a:1, why:\"Le brouillon te permet de le retrouver, de te relire après une pause et d'éviter un envoi raté.\" },\n  { part:1, q:\"Que se passe-t-il quand tu mets toute la classe en « Cc » ?\", o:[\"Chacun voit toutes les adresses\",\"Personne ne reçoit le mail\",\"Les adresses restent cachées\"], a:0, why:\"En « Cc », les adresses sont visibles par tous. Pour un groupe qui ne se connaît pas, utilise « Cci ».\" },\n  { part:1, q:\"Que mets-tu en « Cc » ?\", o:[\"Les personnes qui doivent agir\",\"Les personnes qui doivent juste être au courant\",\"Les personnes dont l'adresse doit rester cachée\"], a:1, why:\"« À » : ceux qui agissent. « Cc » : ceux qui sont informés. « Cci » : copie cachée.\" },\n  { part:1, q:\"Où place-t-on la formule de politesse ?\", o:[\"Au tout début du mail\",\"Juste avant la signature\",\"Après la signature\"], a:1, why:\"L'ordre naturel : appel, présentation, demande, politesse, signature.\" },\n  { part:3, q:\"« Bonjour Madame Sophie, » : quelle est l'erreur ?\", o:[\"Le prénom avec « Madame »\",\"La virgule\",\"Le mot « Bonjour »\"], a:0, why:\"Madame ou Monsieur se met avec le nom de famille, jamais avec le prénom.\" },\n  { part:3, q:\"Dans un mail à un recruteur, quel passage est une erreur ?\", o:[\"« Mon CV est en pièce jointe. »\",\"« Salut, »\",\"« Je suis disponible en juillet. »\"], a:1, why:\"« Salut » est beaucoup trop familier pour une candidature.\" },\n  { part:3, q:\"Comment corriger « J'ai pas pu finir mon devoir » ?\", o:[\"« Je n'ai pas pu finir mon devoir »\",\"« J'ai pas pus finir mon devoir »\",\"« Jai pas pu finir mon devoir »\"], a:0, why:\"À l'écrit, la négation garde le « ne ».\" },\n  { part:3, q:\"L'objet « URGENT !!!! » pour demander un délai : que faire ?\", o:[\"Le garder, ça attire l'attention\",\"Le remplacer par « Devoir de géographie : demande de délai »\",\"Le passer en minuscules\"], a:1, why:\"L'objet doit dire de quoi tu parles, pas crier.\" },\n  { part:3, q:\"Tu mets toute ta classe en copie d'un mail à ta prof. Qu'en penser ?\", o:[\"C'est une bonne idée, tout le monde est informé\",\"C'est inutile : seules les personnes concernées doivent être en copie\",\"C'est obligatoire\"], a:1, why:\"Une copie sert à informer ceux qui ont besoin de savoir, pas tout le monde.\" },\n  { part:3, q:\"Quel mot est une abréviation à éviter dans un mail formel ?\", o:[\"Bonjour\",\"pk\",\"Cordialement\"], a:1, why:\"« pk » est du langage SMS : écris « pourquoi » ou « car » en entier.\" },\n  { part:4, q:\"Quel mail au directeur est le mieux écrit ?\", o:[\"« Salut, je veux un club de jeux vidéo, répondez vite. »\",\"« Bonjour Monsieur Vandenberg, serait-il possible de vous présenter mon projet de club de jeux vidéo la semaine prochaine ? »\",\"« CLUB JEUX VIDEO !!! »\"], a:1, why:\"Appel correct, demande claire, ton poli et proposition de rendez-vous.\" },\n  { part:4, q:\"Quel est le bon ordre d'un mail ?\", o:[\"Appel, présentation, demande, politesse, signature\",\"Politesse, appel, demande, signature, présentation\",\"Demande, appel, signature, politesse, présentation\"], a:0, why:\"On commence par saluer, on se présente, on demande, on conclut poliment, on signe.\" },\n  { part:4, q:\"Tu invites une amie à ton anniversaire. Qu'est-ce qui ne doit pas manquer ?\", o:[\"Une formule du type « Veuillez agréer… »\",\"Le jour, l'heure et le lieu\",\"Un numéro de commande\"], a:1, why:\"Même entre amis, l'essentiel est de savoir quand et où.\" },\n  { part:4, q:\"Quelle signature convient pour une candidature ?\", o:[\"J.F.\",\"Jules\",\"Jules Fabre\"], a:2, why:\"Dans un mail formel, on signe de son prénom et de son nom.\" },\n  { part:4, q:\"Tu réclames un colis perdu. Que donnes-tu en premier ?\", o:[\"Ton humeur\",\"Le numéro de commande et les dates\",\"Un avis sur le site\"], a:1, why:\"Le service client doit retrouver ta commande tout de suite.\" },\n  { part:4, q:\"Ton mail contient « presse » à la place de « présentation ». Que fais-tu ?\", o:[\"Rien, c'est presque pareil\",\"Je me relis et je corrige le mot\",\"Je supprime la phrase\"], a:1, why:\"Un mot à la place d'un autre change le sens : relis-toi toujours avant d'envoyer.\" }\n];\nconst BANK = () => [\n  ...QCM.comprendre.map(q => ({ ...q, part:1 })),\n  ...QCM.adapter.map(q => ({ ...q, part:2 })),\n  ...BANK_EXTRA\n];\nconst FQ_COUNT = 10;\nfunction drawFinalDeck(){\n  const bank = shuffle(BANK()), deck = [];\n  [1,2,3,4].forEach(pt => bank.filter(q => q.part === pt).slice(0,2).forEach(q => deck.push(q)));\n  bank.filter(q => !deck.includes(q)).slice(0, FQ_COUNT - deck.length).forEach(q => deck.push(q));\n  return shuffle(deck).map(q => { const idx = shuffle(q.o.map((_,i) => i)); return { ...q, o:idx.map(i => q.o[i]), a:idx.indexOf(q.a) }; });\n}\n\nconst E = (t, fix, why, opts) => ({ t, err:true, fix, why, opts });\nconst QUIZ = [\n  { title:'Tom postule pour un job étudiant', reader:{ who:'Mme Leroy', role:'Libraire, Page 7', emoji:'👩‍💼',\n      lines:['Je passe au candidat suivant.','Hum… trop de maladresses pour ce poste.','Il y a du potentiel, mais certains détails me gênent.','Presque ! Un dernier détail me chagrine.','Je le convoque pour un entretien !'] },\n    head:[{label:'À',segs:['jobs@librairie-page7.be']},{label:'Objet',segs:[E('Candidature','Candidature : job étudiant été (vendeur)','Trop vague : le recruteur gère plusieurs offres.',['Candidature !!!','Job'])]}],\n    body:[\n      [E('Salut,','Madame, Monsieur,','Beaucoup trop familier pour une candidature.',['Coucou,','Bonjour toi,'])],\n      [\"Je m'appelle Tom Lejeune, j'ai 17 ans et je suis en 5e secondaire.\"],\n      ['Je suis ',E('TRÈS motivé','très motivé',\"Les majuscules donnent l'impression de crier.\",['Très Motivé','TRES MOTIVÉ']),' pour ',E('bosser','travailler','Registre familier.',['taffer','bûcher']),' chez vous cet été',E(' !!!','.','Un seul point suffit, surtout dans un mail formel.',[' !!',' ???'])],\n      ['Je suis disponible du 1er juillet au 31 août. Mon CV est en pièce jointe.'],\n      [E('Merci de me répondre vite.','Je reste à votre disposition pour un entretien.',\"Ça sonne comme un ordre adressé au recruteur.\",['Répondez-moi vite SVP.','Dites-moi si ça marche.'])],\n      [E('Bizz',\"Je vous prie d'agréer, Madame, Monsieur, mes salutations distinguées.\",'Formule de politesse réservée aux proches.',['Cdlt','À+'])],\n      [E('Tom','Tom Lejeune, 0470 12 34 56','Nom complet et moyen de contact attendus.',['Tom L.','Tomtom'])],\n      [E('Pièces jointes : aucune','CV-Tom-Lejeune.pdf',\"Le mail annonce un CV… qui n'est pas joint.\",['CV.pdf','mon cv final v2 (1).docx'])]\n    ] },\n  { title:'Léa écrit à sa prof', reader:{ who:'Mme Dupont', role:'Professeure de géographie', emoji:'👩‍🏫',\n      lines:[\"Je ne comprends pas bien qui m'écrit ni pourquoi…\",\"Hmm, ce mail est confus.\",\"Je vois à peu près ce qu'elle veut.\",\"Presque parfait, merci Léa !\",\"Aucun souci Léa, remets-le lundi.\"] },\n    head:[{label:'À',segs:['s.dupont@institut-stmichel.be']},{label:'Cc',segs:[E('classe-4B@institut-stmichel.be','(vide)',\"Toute la classe n'a pas besoin d'être au courant.\",[\"Le directeur de l'école\",\"Toute l'école\"])]},{label:'Objet',segs:[E('URGENT !!!!','Devoir de géographie : demande de délai',\"L'objet doit dire de quoi tu parles, pas crier.\",['Urgent svp','Question'])]}],\n    body:[\n      [E('Bonjour Madame Sophie,','Bonjour Madame Dupont,','Madame ou Monsieur + nom de famille, jamais le prénom.',['Bonjour Sophie,','Bonjour Mme,'])],\n      ['Je suis Léa Martin, élève de 4e B.'],\n      [E(\"J'ai pas pu\",\"Je n'ai pas pu\",\"À l'écrit, la négation garde le « ne ».\",[\"Je ne pu pas\",\"J'ai ne pas pu\"]),' finir le devoir de géographie ',E('pk','car',\"Pas d'abréviation SMS.\",['pcq','parceque']),\" j'étais malade du 3 au 6 octobre.\"],\n      ['Serait-il possible de vous le remettre lundi 13 octobre ?'],\n      ['Je vous remercie par avance. Bien cordialement,'],\n      ['Léa Martin'],\n      ['4e B, Institut Saint-Michel']\n    ] }\n];\n\nconst SMS = /\\b(slt|stp|svp|mdr|ptdr|pk|pq|bcp|jsp|tkt|dsl|cc|bjr|cdlt|jpp|wesh)\\b/i;\n\nconst PARTS = [\n  { k:'comprendre', n:1, title:'Comprendre un mail', hl:'un mail', img:'keypace-mascot-idea', desc:\"Les 14 cases d'un mail, une par une : destinataire, copies, objet, texte, pièce jointe, priorité, brouillon, réponses et relance. Fais défiler : chaque étape allume la zone correspondante.\", prev:['14 étapes','Mail annoté','Quiz'] },\n  { k:'adapter', n:2, title:'Adapter le ton', hl:'le ton', img:'keypace-mascots-duo', desc:\"La structure reste la même. Ce qui change : le ton, la formule d'appel et la formule de politesse.\", prev:['7 destinataires','Formalité','Quiz'] },\n  { k:'reperer', n:3, title:'Repérer les erreurs', hl:'les erreurs', img:'keypace-mascot-conjugaison-reflexion', desc:\"D'abord tu repères les erreurs d'un mail, puis tu les corriges et tu vois le lecteur réagir en direct.\", prev:['2 mails','Repère + corrige','Le lecteur réagit'] },\n  { k:'entrainer', n:4, title:\"S'entraîner à écrire\", hl:'à écrire', img:'keypace-mascot-bureau-complet', desc:\"Choisis une situation et rédige le mail. La checklist se valide au fur et à mesure.\", prev:['12 situations','Checklist en direct'] }\n];\nconst hlTitle = p => p.title.replace(p.hl, `<em>${p.hl}</em>`);\n\nconst $ = s => document.querySelector(s);\nconst store = { get(){ try{ return JSON.parse(localStorage.getItem('kp-mail-done')||'{}'); }catch(e){ return {}; } },\n  set(o){ try{ localStorage.setItem('kp-mail-done', JSON.stringify(o)); }catch(e){} } };\nlet done = store.get(), io = null, recTimer = null;\nfunction completePart(k){\n  done[k] = true; store.set(done);\n  const f = $('#finish'), p = PARTS.find(x => x.k === k);\n  if (f && '#mail/'+p.n === location.hash){ f.textContent = 'Terminée ✓'; f.className = 'btn ok'; const r = $('#restart'); if (r) r.hidden = false; refreshNext(); }\n}\nconst allDone = () => PARTS.every(p => done[p.k]);\nconst BEST_KEY = 'kp-mail-quiz-best';\nconst getBest = () => { try{ return +localStorage.getItem(BEST_KEY) || 0; }catch(e){ return 0; } };\nconst setBest = n => { try{ localStorage.setItem(BEST_KEY, String(n)); }catch(e){} };\nfunction refreshNext(){\n  const nx = $('#next4'); if (!nx) return;\n  if (allDone()){ nx.textContent = 'Quiz final →'; nx.onclick = () => { location.hash = 'mail/quiz'; }; }\n}\nfunction show(id){ document.querySelectorAll('.view').forEach(v => v.classList.toggle('on', v.id === id)); window.scrollTo(0,0); }\n\nfunction route(){\n  if (io){ io.disconnect(); io = null; }\n  clearInterval(recTimer);\n  const h = location.hash.replace('#','');\n  if (h === 'mail') return renderHub();\n  if (h === 'mail/quiz') return allDone() ? renderFinalQuiz() : renderHub();\n  const m = h.match(/^mail\\/(\\d)$/);\n  if (m && PARTS[m[1]-1]) return renderLesson(PARTS[m[1]-1]);\n  renderHub();\n}\nwindow.addEventListener('hashchange', route);\ndocument.addEventListener('click', e => {\n  const g = e.target.closest('[data-go]');\n  if (g){ if (g.dataset.go === 'cours'){ location.href = '/?view=lessons'; return; } location.hash = g.dataset.go === 'hub' ? 'mail' : g.dataset.go; return; }\n  if (e.target.id === 'restart'){ const p = PARTS.find(x => '#mail/'+x.n === location.hash); if (p){ renderLesson(p); } return; }\n  if (e.target.id === 'reset-all'){ if (confirm(\"Effacer ta progression dans ce module ? Tu pourras tout refaire depuis le début.\")){ done = {}; store.set(done); try{ localStorage.removeItem(BEST_KEY); }catch(err){} renderHub(); } return; }\n  if (e.target.id === 'finish'){ const p = PARTS.find(x => '#mail/'+x.n === location.hash); if (p){ completePart(p.k); location.hash = 'mail'; } }\n});\n\nconst MINI = {\n  comprendre:`<div class=\"mw\"><div class=\"dots\"><i></i><i></i><i></i></div><div class=\"ml\"></div><div class=\"ml\"></div><div class=\"ml\"></div><div class=\"ml\"></div></div>`,\n  adapter:`<div class=\"m2\"><div class=\"who\" id=\"rec-who\">Ami</div><div class=\"bars\" id=\"rec-bars\">${[1,2,3,4,5].map(()=>'<span></span>').join('')}</div></div>`,\n  reperer:`<div class=\"mw m3\"><span class=\"sw\"><span class=\"bad\">Salut,</span><span class=\"good\">Bonjour,</span></span><br><span>J'ai été malade, serait-il possible de…</span><span class=\"sw\"><span class=\"bad\">Bizz</span><span class=\"good\">Cordialement,</span></span></div>`,\n  entrainer:`<div class=\"m4\"><div class=\"typed\"><span>Bonjour Madame Dupont,</span></div><div class=\"cks\"><i></i><i></i><i></i><i></i></div></div>`\n};\nfunction partCard(p){\n  const d = done[p.k];\n  return `<button class=\"part ${d?'done':''}\" onclick=\"location.hash='mail/${p.n}'\">\n    <div class=\"mini\">${MINI[p.k]}</div>\n    ${d ? '<span class=\"badge-done\">Terminée ✓</span>' : ''}\n    <h3>${p.title}</h3><p>${p.desc}</p>\n    <div class=\"prev\">${p.prev.map(x => `<span>${x}</span>`).join('')}</div>\n    <div class=\"foot\"><span class=\"dur\">Partie ${p.n}</span><span class=\"cta\">${d?'Revoir':'Ouvrir'} →</span></div>\n  </button>`;\n}\nfunction startRecDemo(){\n  const seq = [{l:'Ami',f:1},{l:'Collègue',f:2},{l:'Professeur',f:4},{l:'Recruteur',f:5}]; let i = 0;\n  const tick = () => { const w = $('#rec-who'), b = $('#rec-bars'); if (!w || !b) return;\n    const c = seq[i++ % seq.length]; w.textContent = c.l; [...b.children].forEach((x,j) => x.className = j < c.f ? 'f' : ''); };\n  tick(); recTimer = setInterval(tick, 1700);\n}\nfunction quizBanner(n){\n  const all = n === PARTS.length, best = getBest();\n  if (!all) return `<section class=\"qbanner locked\">\n    <img src=\"/images/keypace-mascot-cheer.webp\" alt=\"\">\n    <div class=\"qb-txt\"><span class=\"qb-tag\">Quiz final · 🔒 Verrouillé</span><h2>Le quiz des mails</h2>\n      <p>Termine les 4 parties pour le débloquer. Il reprend tout le module, question après question, au hasard.</p></div>\n    <div class=\"qb-act\"><div class=\"qb-prog\"><i style=\"width:${n/4*100}%\"></i></div><span style=\"font-size:12.5px;color:var(--muted)\">${n}/4 parties terminées</span></div></section>`;\n  return `<section class=\"qbanner\">\n    <img src=\"/images/keypace-mascot-cheer.webp\" alt=\"\">\n    <div class=\"qb-txt\"><span class=\"qb-tag\">Module terminé, bravo !</span><h2>Teste-toi avec le quiz <em>des mails</em></h2>\n      <p>${FQ_COUNT} questions tirées au hasard dans toutes les parties, une à la fois. Tu peux rejouer autant de fois que tu veux, avec de nouvelles questions.</p>\n      <div class=\"qb-meta\"><span>${FQ_COUNT} questions</span><span>Au hasard</span>${best ? `<span>Meilleur score : ${best}/${FQ_COUNT}</span>` : ''}</div></div>\n    <div class=\"qb-act\"><button class=\"btn primary\" onclick=\"location.hash='mail/quiz'\" style=\"font-size:16px;padding:14px 26px\">Jouer →</button></div></section>`;\n}\nfunction renderHub(){\n  const n = PARTS.filter(p => done[p.k]).length, all = n === PARTS.length;\n  $('#hub-prog').textContent = n + '/4 parties';\n  $('#hub-bar').style.width = (n/4*100) + '%';\n  $('#hub-meta').innerHTML = `<div class=\"ring\" style=\"--p:${n/4*100}\"><i>${n}/4</i></div><span>parties terminées</span>${n ? '<button class=\"linkbtn\" id=\"reset-all\">Réinitialiser ma progression</button>' : ''}`;\n  const nextK = all ? null : (PARTS.find(p => !done[p.k]) || {}).k, mascots = ['cheer','idea','books','desk'];\n  $('#parts-host').innerHTML = `<div class=\"road\">${PARTS.map((p,i) => `\n    <div class=\"stop ${done[p.k]?'done':''} ${p.k===nextK?'next':''}\">\n      ${partCard(p)}\n      <div class=\"node\">${done[p.k] ? '✓' : p.n}</div>\n      <div class=\"side\">${p.k===nextK ? `<img src=\"/images/keypace-mascot-${mascots[i]}.webp\" alt=\"\"><span class=\"bubble\">${n ? 'Tu en es là !' : 'Commence ici !'}</span>` : ''}</div>\n    </div>`).join('')}</div>${quizBanner(n)}`;\n  startRecDemo();\n  show('v-hub');\n}\n\n/* ======================= QUIZ FINAL ======================= */\nfunction renderFinalQuiz(){\n  $('#crumb-part').textContent = 'Quiz final';\n  $('#lesson-pos').textContent = 'Quiz final';\n  $('#lesson-hero').innerHTML = `<div class=\"hero small\"><div class=\"wrap\"><div class=\"txt\">\n      <span class=\"tag\">Quiz final</span><h1>Le quiz <em>des mails</em></h1><p>${FQ_COUNT} questions tirées au hasard dans toutes les parties. Une à la fois, dans un ordre différent à chaque partie.</p></div>\n      <img src=\"/images/keypace-mascot-cheer.webp\" alt=\"\"></div></div>`;\n  $('#lesson-root').innerHTML = `<div id=\"fq\"></div><div class=\"lesson-foot\"><button class=\"btn\" onclick=\"location.hash='mail'\">← Retour au module</button><span></span></div>`;\n  show('v-lesson');\n  initFinalQuiz($('#fq'));\n}\nfunction initFinalQuiz(el){\n  let deck = drawFinalDeck(), i = 0, picked = null, res = [];\n  const draw = () => {\n    if (i >= deck.length){\n      const sc = res.filter(Boolean).length, N = deck.length, best = getBest(), isBest = sc > best;\n      if (isBest) setBest(sc);\n      const msg = sc === N ? 'Sans faute ! Tu maîtrises les mails.' : sc >= N*0.8 ? 'Excellent, presque parfait.' : sc >= N*0.5 ? 'Bien joué, encore quelques points à revoir.' : 'Pas facile ! Reprends les parties puis retente.';\n      const missed = deck.map((q,k) => ({ q, ok:res[k] })).filter(x => !x.ok);\n      el.innerHTML = `<section class=\"qz\" style=\"margin-top:34px\"><div class=\"qz-top\"><h2>Résultat du quiz</h2></div>\n        <div class=\"res\"><div class=\"score\">${sc}/${N}</div><div><p style=\"font-size:17px;font-weight:600\">${msg}</p><p style=\"color:var(--muted);font-size:14px\">${isBest && sc > 0 ? 'Nouveau meilleur score !' : `Meilleur score : ${Math.max(best, sc)}/${N}`}</p></div></div>\n        ${missed.length ? `<div class=\"miss-list\"><b style=\"font-family:'Bricolage Grotesque',sans-serif;font-size:17px\">À revoir</b>${missed.map(x => `<div><span class=\"fq-part\">Partie ${x.q.part}</span> ${x.q.q}<small>Bonne réponse : ${x.q.o[x.q.a]}. ${x.q.why}</small></div>`).join('')}</div>` : ''}\n        <div class=\"btnrow\" style=\"margin-top:22px\"><button class=\"btn primary\" id=\"fq-again\">Rejouer avec de nouvelles questions</button><button class=\"btn\" onclick=\"location.hash='mail'\">Retour au module</button></div></section>`;\n      $('#fq-again').onclick = () => { deck = drawFinalDeck(); i = 0; picked = null; res = []; draw(); window.scrollTo(0,0); };\n      return;\n    }\n    const c = deck[i];\n    el.innerHTML = `<section class=\"qz\" style=\"margin-top:34px\">\n      <div class=\"qz-top\"><span class=\"fq-part\">Partie ${c.part} · ${PARTS[c.part-1].title}</span><div class=\"dots\">${deck.map((_,j) => `<i class=\"${j<i?(res[j]?'ok':'ko'):j===i?'cur':''}\"></i>`).join('')}</div></div>\n      <div class=\"q\">${c.q}</div>\n      <div class=\"opts\">${c.o.map((o,j) => {\n        let cl = 'opt'; if (picked !== null){ if (j === c.a) cl += ' right'; else if (j === picked) cl += ' wrong'; }\n        return `<button class=\"${cl}\" data-j=\"${j}\" ${picked!==null?'disabled':''}><span class=\"k\">${'ABCD'[j]}</span>${o}</button>`; }).join('')}</div>\n      ${picked !== null ? `<div class=\"fb ${picked===c.a?'ok':'ko'}\"><b>${picked===c.a?'Exact.':'Pas tout à fait.'}</b> ${c.why}</div>\n        <div class=\"btnrow\" style=\"margin-top:16px\"><button class=\"btn primary\" id=\"fq-next\">${i<deck.length-1?'Question suivante →':'Voir mon résultat'}</button></div>` : ''}\n      <p style=\"margin-top:18px;font-size:13px;color:var(--muted)\">Question ${i+1} sur ${deck.length}</p>\n    </section>`;\n    el.querySelectorAll('.opt').forEach(b => b.onclick = () => { picked = +b.dataset.j; res[i] = picked === c.a; draw(); });\n    const nx = $('#fq-next'); if (nx) nx.onclick = () => { i++; picked = null; draw(); };\n  };\n  draw();\n}\n\nfunction renderLesson(p){\n  $('#crumb-part').textContent = p.title;\n  $('#lesson-pos').textContent = 'Partie ' + p.n + ' sur 4';\n  $('#lesson-hero').innerHTML = `<div class=\"hero small\"><div class=\"wrap\"><div class=\"txt\">\n      <span class=\"tag\">Partie ${p.n} sur 4</span><h1>${hlTitle(p)}</h1><p>${p.desc}</p></div>\n      <img src=\"/images/${p.img}.webp\" alt=\"\"></div></div>`;\n  $('#lesson-root').innerHTML = '<div id=\"lesson-body\"></div><div id=\"lesson-quiz\"></div>' + footer(p);\n  show('v-lesson');\n  ({ comprendre:initComprendre, adapter:initAdapter, reperer:initReperer, entrainer:initEntrainer })[p.k]($('#lesson-body'));\n  if (QCM[p.k]) initQCM($('#lesson-quiz'), p);\n}\nfunction footer(p){\n  const prev = PARTS[p.n-2], next = PARTS[p.n];\n  const nextBtn = next ? `<button class=\"btn dark\" onclick=\"location.hash='mail/${next.n}'\">${next.title} →</button>`\n    : (allDone() ? `<button class=\"btn dark\" id=\"next4\" onclick=\"location.hash='mail/quiz'\">Quiz final →</button>` : `<button class=\"btn dark\" id=\"next4\" onclick=\"location.hash='mail'\">Retour au module</button>`);\n  return `<div class=\"lesson-foot\">\n    ${prev ? `<button class=\"btn\" onclick=\"location.hash='mail/${prev.n}'\">← ${prev.title}</button>` : `<button class=\"btn\" onclick=\"location.hash='mail'\">← Retour au module</button>`}\n    <span class=\"foot-grp\"><button class=\"btn\" id=\"restart\" ${done[p.k]?'':'hidden'}>↺ Recommencer cette partie</button>\n    <button class=\"btn ${done[p.k]?'ok':'primary'}\" id=\"finish\">${done[p.k] ? 'Terminée ✓' : 'Terminer cette partie'}</button></span>\n    ${nextBtn}\n  </div>`;\n}\n\nconst shuffleQ = list => list.map(q => { const idx = shuffle(q.o.map((_,i) => i)); return { ...q, o:idx.map(i => q.o[i]), a:idx.indexOf(q.a) }; });\nfunction initQCM(el, p){\n  let Q = shuffleQ(QCM[p.k]); let i = 0, picked = null, res = [];\n  const draw = () => {\n    if (i >= Q.length){\n      const s = res.filter(Boolean).length;\n      const msg = s === Q.length ? 'Sans faute, bravo !' : s >= Q.length-1 ? 'Presque parfait.' : s >= 2 ? 'Bon début, relis les points manqués.' : 'Reprends la partie, puis retente.';\n      el.innerHTML = `<section class=\"qz\"><div class=\"qz-top\"><h2>Quiz terminé</h2></div>\n        <div class=\"res\"><div class=\"score\">${s}/${Q.length}</div><div><p style=\"font-size:17px;font-weight:600\">${msg}</p><p style=\"color:var(--muted);font-size:14px\">Partie validée : tu peux passer à la suite quand tu veux.</p></div></div>\n        <div class=\"btnrow\" style=\"margin-top:20px\"><button class=\"btn\" id=\"qz-again\">Refaire le quiz</button>${PARTS[p.n] ? `<button class=\"btn primary\" onclick=\"location.hash='mail/${p.n+1}'\">${PARTS[p.n].title} →</button>`:''}</div></section>`;\n      $('#qz-again').onclick = () => { Q = shuffleQ(QCM[p.k]); i = 0; picked = null; res = []; draw(); };\n      completePart(p.k); return;\n    }\n    const c = Q[i];\n    el.innerHTML = `<section class=\"qz\">\n      <div class=\"qz-top\"><h2>Petit quiz <em>de fin de partie</em></h2><div class=\"dots\">${Q.map((_,j) => `<i class=\"${j<i?(res[j]?'ok':'ko'):j===i?'cur':''}\"></i>`).join('')}</div></div>\n      <div class=\"q\">${c.q}</div>\n      <div class=\"opts\">${c.o.map((o,j) => {\n        let cl = 'opt'; if (picked !== null){ if (j === c.a) cl += ' right'; else if (j === picked) cl += ' wrong'; }\n        return `<button class=\"${cl}\" data-j=\"${j}\" ${picked!==null?'disabled':''}><span class=\"k\">${'ABCD'[j]}</span>${o}</button>`; }).join('')}</div>\n      ${picked !== null ? `<div class=\"fb ${picked===c.a?'ok':'ko'}\"><b>${picked===c.a?'Exact.':'Pas tout à fait.'}</b> ${c.why}</div>\n        <div class=\"btnrow\" style=\"margin-top:16px\"><button class=\"btn primary\" id=\"qz-next\">${i<Q.length-1?'Question suivante →':'Voir mon résultat'}</button></div>` : ''}\n    </section>`;\n    el.querySelectorAll('.opt').forEach(b => b.onclick = () => { picked = +b.dataset.j; res[i] = picked === c.a; draw(); });\n    const nx = $('#qz-next'); if (nx) nx.onclick = () => { i++; picked = null; draw(); };\n  };\n  draw();\n}\n\nfunction initComprendre(el){\n  const z = (k, inner) => `<div class=\"zone\" data-z=\"${k}\">${inner}</div>`;\n  el.innerHTML = `<div class=\"anat\">\n    <div>${STEPS.map((s,i) => `<article class=\"step\" data-i=\"${i}\">\n      <div class=\"t\"><span class=\"n\">${String(i+1).padStart(2,'0')}</span><h3>${s.t}</h3></div>\n      <p class=\"x\">${s.x}</p>\n      <div style=\"display:grid;gap:10px\"><div class=\"tip\"><b>Astuce :</b> ${s.tip}</div><div class=\"avoid\"><b>À éviter :</b> ${s.a}</div></div>\n    </article>`).join('')}</div>\n    <div class=\"stk\">\n      <div class=\"cap\"><span>Exemple : Léa écrit à sa prof</span><b id=\"active-label\"></b></div>\n      <div class=\"mailwin\">\n        <div class=\"bar\"><i></i><i></i><i></i><span>Nouveau message</span><span class=\"tbtn zone\" data-z=\"draft\" style=\"margin-left:auto\">💾 Brouillon enregistré</span><span class=\"tbtn zone\" data-z=\"prio\" style=\"color:#C0392B;font-weight:700\">! Importance haute</span></div>\n        <div class=\"mhead\">\n          <div class=\"mrow zone\" data-z=\"to\"><span class=\"l\">À</span><span>s.dupont@institut-stmichel.be</span></div>\n          <div class=\"mrow zone\" data-z=\"cc\"><span class=\"l\">Cc</span><span>titulaire.4b@institut-stmichel.be</span></div>\n          <div class=\"mrow zone\" data-z=\"cc\"><span class=\"l\">Cci</span><span style=\"color:#8A8279\">les autres ne voient pas cette adresse</span></div>\n          <div class=\"mrow zone\" data-z=\"subject\"><span class=\"l\">Objet</span><span style=\"font-weight:600\">Devoir de géographie : demande de délai</span></div>\n        </div>\n        <div class=\"mbody\">\n          ${z('greet','Bonjour Madame Dupont,')}\n          ${z('intro','Je suis Léa Martin, élève de 4e B.')}\n          ${z('body',\"J'ai été malade du 3 au 6 octobre et je n'ai pas pu terminer le devoir de géographie.\")}\n          ${z('ask','Serait-il possible de vous le remettre lundi 13 octobre ?')}\n          ${z('polite','Je vous remercie par avance pour votre compréhension.<br>Bien cordialement,')}\n          ${z('sign','<strong>Léa Martin</strong><br><span style=\"color:#6B645C;font-size:14px\">4e B, Institut Saint-Michel</span>')}\n          <div class=\"attach zone\" data-z=\"attach\">📎 <span>certificat-medical.pdf</span><small>84 Ko</small></div>\n          <div class=\"replybar zone\" data-z=\"reply\"><span>↩ Répondre</span><span>↩↩ Répondre à tous</span><span>➦ Transférer</span></div>\n          <div class=\"follow zone\" data-z=\"follow\">⏰ Pas de réponse depuis 5 jours ? Un rappel poli, dans le même fil.</div>\n        </div>\n      </div>\n    </div>\n  </div>`;\n  const steps = [...el.querySelectorAll('.step')], zones = [...el.querySelectorAll('[data-z]')];\n  const set = i => {\n    steps.forEach((s,j) => s.classList.toggle('on', j === i));\n    zones.forEach(zn => zn.classList.toggle('on', zn.dataset.z === STEPS[i].z));\n    $('#active-label').textContent = String(i+1).padStart(2,'0') + ' · ' + STEPS[i].t;\n  };\n  set(0);\n  io = new IntersectionObserver(es => es.forEach(en => { if (en.isIntersecting) set(+en.target.dataset.i); }), { rootMargin:'-45% 0px -45% 0px' });\n  steps.forEach(s => io.observe(s));\n}\n\nfunction initAdapter(el){\n  let cur = 'prof';\n  const draw = () => {\n    const R = REC[cur];\n    el.innerHTML = `<div class=\"chips\">${CORE.map(k => `<button class=\"chip ${k===cur?'on':''}\" data-k=\"${k}\">${REC[k].label}</button>`).join('')}</div>\n    <div class=\"rec\">\n      <div>\n        <div class=\"lab\">Niveau de formalité : ${R.level}</div>\n        <div class=\"bars\">${[1,2,3,4,5].map(i => `<span class=\"${i<=R.f?'f':''}\"></span>`).join('')}</div>\n        <div class=\"pills\"><span class=\"pill\">${R.register}</span><span class=\"pill\">${R.length}</span></div>\n        <p class=\"note\">${R.note}</p>\n      </div>\n      <div class=\"recgrid\">\n        <div class=\"exgrid\"><div class=\"ex\"><div class=\"lab\">Formule d'appel</div><div>${R.greet}</div></div><div class=\"ex\"><div class=\"lab\">Formule de politesse</div><div>${R.polite}</div></div></div>\n        <div class=\"exgrid\"><div class=\"ex ok\"><div class=\"lab\">À faire</div><div>${R.yes}</div></div><div class=\"ex ko\"><div class=\"lab\">À éviter</div><div>${R.no}</div></div></div>\n      </div>\n    </div>\n    <div style=\"margin-top:20px\"><button class=\"btn\" id=\"try-it\">S'entraîner avec « ${R.label} » →</button></div>`;\n    el.querySelectorAll('.chip').forEach(c => c.onclick = () => { cur = c.dataset.k; draw(); });\n    $('#try-it').onclick = () => { sessionStorage.setItem('kp-train', cur); location.hash = 'mail/4'; };\n  };\n  draw();\n}\n\nconst countErr = k => { let n = 0; const Q = QUIZ[k]; [...Q.head.map(h => h.segs), ...Q.body].forEach(l => l.forEach(s => { if (typeof s !== 'string' && s.err) n++; })); return n; };\nconst shuffle = a => a.map(x => [Math.random(), x]).sort((x,y) => x[0]-y[0]).map(x => x[1]);\n\n/* Partie 3 : en 2 étapes par mail. 1) Repère (on clique les erreurs) 2) Corrige (choix de la bonne forme, le lecteur réagit en direct) */\nlet TOKDRAG = null;\ndocument.addEventListener('pointermove', e => { if (!TOKDRAG) return; const t = document.elementFromPoint(e.clientX, e.clientY)?.closest('.tok'); if (t) TOKDRAG.move(+t.dataset.i); });\ndocument.addEventListener('pointerup', () => { if (TOKDRAG) TOKDRAG.end(); });\nfunction initReperer(el){\n  let qi = 0;\n  const S = QUIZ.map(() => ({ phase:1, picked:{}, checked:false, st:{}, open:null, cache:{}, log:[], msg:null }));\n  const tabs = () => `<div class=\"chips\" style=\"margin:6px 0 14px\">${QUIZ.map((q,i) => `<button class=\"chip ${i===qi?'on':''}\" data-q=\"${i}\">Mail ${i+1}${S[i].phase===3?' ✓':''}</button>`).join('')}</div>`;\n  const stepper = s => `<div class=\"steps2\">\n      <div class=\"s2 ${s.phase===1?'cur':'ok'}\"><b>${s.phase===1?'1':'✓'}</b>Repère les erreurs</div><i></i>\n      <div class=\"s2 ${s.phase>=2?(s.phase===3?'ok':'cur'):(s.checked?'':'lock')}\"><b>${s.phase===3?'✓':'2'}</b>Corrige-les</div></div>`;\n  const wire = (el2) => el2.querySelectorAll('[data-q]').forEach(b => b.onclick = () => { qi = +b.dataset.q; draw(); });\n  const allDone = () => S.every(x => x.phase === 3);\n\n  /* Découpe un mail en mots (tokens) : chaque mot est sélectionnable, seul ou en groupe */\n  const build = Q => {\n    let idx = 0; const errs = [];\n    const segsOf = segs => segs.map(raw => {\n      const g = typeof raw === 'string' ? { t:raw, err:false } : raw;\n      const m = g.t.match(/^(\\s*)([\\s\\S]*?)(\\s*)$/), core = m[2];\n      const toks = (core.match(/\\S+\\s*/g) || []).map(text => ({ i:idx++, text }));\n      let eid = null; if (g.err){ eid = errs.length; errs.push({ g, toks:toks.map(t => t.i) }); }\n      return { lead:m[1], trail:m[3], toks, eid };\n    });\n    return { head:Q.head.map(h => ({ label:h.label, segs:segsOf(h.segs) })), body:Q.body.map(l => segsOf(l)), errs, n:idx };\n  };\n  const drawSpot = () => {\n    const Q = QUIZ[qi], s = S[qi]; if (!s.struct) s.struct = build(Q);\n    const T = s.struct, sel = s.picked;\n    const cnt = e => e.toks.filter(i => sel[i]).length;\n    const foundOf = T.errs.map(e => cnt(e) >= Math.ceil(e.toks.length/2));\n    const errOf = {}; T.errs.forEach((e,k) => e.toks.forEach(i => errOf[i] = k));\n    const nSel = Object.keys(sel).length;\n    let fp = 0, prev = false;\n    for (let i = 0; i < T.n; i++){ const f = sel[i] && errOf[i] === undefined; if (f && !prev) fp++; prev = f; }\n    const seg = sg => {\n      const toks = sg.toks.map(t => {\n        let c = 'tok';\n        if (!s.checked){ if (sel[t.i]) c += ' pick'; }\n        else if (sg.eid === null){ if (sel[t.i]) c += ' fp'; }\n        else if (foundOf[sg.eid]) c += ' good';\n        return `<span class=\"${c}\" data-i=\"${t.i}\">${t.text}</span>`;\n      }).join('');\n      const grp = s.checked && sg.eid !== null && !foundOf[sg.eid] ? `<span class=\"grp miss\">${toks}</span>` : toks;\n      return sg.lead + grp + sg.trail;\n    };\n    const head = T.head.map((h,i) => `<div class=\"qrow\"><span class=\"l\">${h.label}</span><span style=\"line-height:1.7;${i===T.head.length-1?'font-weight:600':''}\">${h.segs.map(seg).join('')}</span></div>`).join('');\n    const body = T.body.map(l => `<div>${l.map(seg).join('')}</div>`).join('');\n    const found = foundOf.filter(Boolean).length, total = T.errs.length;\n    el.innerHTML = tabs() + stepper(s) + `<div class=\"quiz\">\n      <div class=\"mailwin ${s.checked?'locked':''}\" id=\"spot-win\"><div class=\"bar\"><i></i><i></i><i></i><span>${Q.title}</span></div><div class=\"qhead\">${head}</div><div class=\"qbody\">${body}</div></div>\n      <aside class=\"aside\">${!s.checked ? `\n        <span style=\"font-size:15px;line-height:1.55\"><b>${total} erreurs</b> se cachent dans ce mail. Clique sur un mot, ou glisse (ou Maj + clic) pour sélectionner un groupe de mots. Pas besoin de savoir corriger : ça, c'est l'étape 2.</span>\n        <div class=\"btnrow\"><button class=\"btn primary\" id=\"q-check\" ${nSel?'':'disabled'}>Vérifier (<span id=\"q-n\">${nSel}</span> mot${nSel>1?'s':''})</button>${nSel ? '<button class=\"btn\" id=\"q-clear\">Tout effacer</button>' : ''}</div>` : `\n        <div class=\"sc\">${found}/${total} repérées${fp ? ' · '+fp+' fausse'+(fp>1?'s':'')+' alerte'+(fp>1?'s':'') : ''}</div>\n        <div class=\"legend\"><span><i style=\"background:var(--success-soft);box-shadow:inset 0 -2px 0 var(--success)\"></i>Repérée</span><span><i style=\"box-shadow:inset 0 0 0 2px var(--accent)\"></i>Manquée</span><span><i style=\"background:var(--light)\"></i>Fausse alerte</span></div>\n        <span style=\"font-size:14.5px;line-height:1.5;color:var(--body)\">${found===total ? 'Tu as tout repéré.' : 'Les erreurs manquées sont entourées en orange.'} À l'étape 2, tu corriges chacune et tu vois comment ${Q.reader.who} réagit.</span>\n        <div class=\"btnrow\"><button class=\"btn\" id=\"q-retry\">Recommencer</button><button class=\"btn primary\" id=\"q-go\">Passer à la correction →</button></div>`}\n      </aside></div>`;\n    wire(el);\n    const on = (id, fn) => { const b = $(id); if (b) b.onclick = fn; };\n    on('#q-check', () => { s.checked = true; draw(); });\n    on('#q-clear', () => { s.picked = {}; s.last = null; draw(); });\n    on('#q-retry', () => { s.picked = {}; s.checked = false; s.last = null; draw(); });\n    on('#q-go', () => { s.phase = 2; draw(); });\n    if (s.checked) return;\n    /* Sélection : clic, glisser, Maj + clic (souris) ; tap (tactile) */\n    const toks = [...el.querySelectorAll('.tok')];\n    const paint = () => { toks.forEach(t => t.classList.toggle('pick', !!sel[t.dataset.i]));\n      const n = Object.keys(sel).length; const b = $('#q-check'); if (b){ b.disabled = !n; b.innerHTML = `Vérifier (<span id=\"q-n\">${n}</span> mot${n>1?'s':''})`; } };\n    const setRange = (base, a, b, mode) => { const lo = Math.min(a,b), hi = Math.max(a,b); s.picked = { ...base };\n      for (let k = lo; k <= hi; k++){ if (mode) s.picked[k] = true; else delete s.picked[k]; } Object.keys(sel).forEach(k => delete sel[k]); Object.assign(sel, s.picked); s.picked = sel; paint(); };\n    let lastPT = 'mouse';\n    toks.forEach(t => {\n      t.addEventListener('pointerdown', e => {\n        lastPT = e.pointerType; if (e.pointerType === 'touch') return;\n        e.preventDefault(); const i = +t.dataset.i;\n        if (e.shiftKey && s.last !== null){ setRange({ ...sel }, s.last, i, true); return; }\n        const mode = !sel[i], base = { ...sel }; setRange(base, i, i, mode); s.last = i;\n        TOKDRAG = { move: j => setRange(base, i, j, mode), end: () => { TOKDRAG = null; draw(); } };\n      });\n      t.addEventListener('click', () => { if (lastPT === 'touch'){ const i = +t.dataset.i; if (sel[i]) delete sel[i]; else sel[i] = true; s.last = i; draw(); } });\n    });\n  };\n\n  const drawFix = () => {\n    const Q = QUIZ[qi], s = S[qi]; let total = 0, ok = 0;\n    const seg = (segs, li) => segs.map((raw, si) => {\n      const g = typeof raw === 'string' ? { t:raw, err:false } : raw, id = qi+'-'+li+'-'+si;\n      if (g.err) total++;\n      if (!g.err) return `<span class=\"seg\" data-ok=\"1\">${g.t}</span>`;\n      if (s.st[id] === 'ok'){ ok++; return `<span class=\"seg good\">${g.fix}</span>`; }\n      let pop = '';\n      if (s.open === id){\n        s.cache[id] = s.cache[id] || shuffle([g.fix, ...g.opts]);\n        pop = `<span class=\"pop\"><span class=\"h\">Par quoi le remplacer ?</span>${s.cache[id].map(o => `<button data-pick=\"${id}\" data-right=\"${o===g.fix?1:0}\">${o}</button>`).join('')}</span>`;\n      }\n      return `<span class=\"seg bad\" data-id=\"${id}\" data-err=\"1\">${g.t}${pop}</span>`;\n    }).join('');\n    const head = Q.head.map((h,i) => `<div class=\"qrow\"><span class=\"l\">${h.label}</span><span style=\"line-height:1.7;${i===Q.head.length-1?'font-weight:600':''}\">${seg(h.segs,'h'+i)}</span></div>`).join('');\n    const body = Q.body.map((l,i) => `<div>${seg(l,'b'+i)}</div>`).join('');\n    const pct = ok/total, r = Q.reader, line = r.lines[pct === 1 ? 4 : Math.min(3, Math.floor(pct*4))];\n    const full = ok === total;\n    if (full && s.phase === 2){ s.phase = 3; if (allDone()) completePart('reperer'); }\n    el.innerHTML = tabs() + stepper(s) + `<p class=\"hintbar\">Clique sur chaque passage souligné en vagues et choisis la bonne correction. Regarde ${r.who} réagir.</p>\n      <div class=\"quiz\"><div class=\"mailwin\"><div class=\"bar\"><i></i><i></i><i></i><span>${Q.title}</span></div><div class=\"qhead\">${head}</div><div class=\"qbody\">${body}</div></div>\n      <aside class=\"reader\">\n        <div class=\"rd-who\"><div class=\"rd-av\">${r.emoji}</div><div><b>${r.who}</b><small>${r.role}</small></div></div>\n        <div class=\"rd-bubble ${pct===1?'top':pct<.25?'low':''}\">« ${line} »</div>\n        <div><div class=\"rd-lab\"><span>Bonne impression</span><b style=\"color:var(--mod-d)\">${ok}/${total}</b></div><div class=\"meter ${pct===1?'full':''}\"><i style=\"width:${pct*100}%\"></i></div></div>\n        ${s.msg ? `<div class=\"fb ko\" style=\"margin:0\"><b>Pas tout à fait.</b> ${s.msg}</div>` : ''}\n        ${s.log.length ? `<div class=\"expl\">${s.log.map(e => `<div><span><s>${e.t.trim()}</s> → <strong>${e.fix}</strong></span><small>${e.why}</small></div>`).join('')}</div>` : ''}\n        ${full ? `<div class=\"fb ok\" style=\"margin:0\"><b>Mail corrigé !</b> ${allDone() ? 'Partie validée.' : 'Passe à l\\'autre mail.'}</div><div class=\"btnrow\">${allDone() ? `<button class=\"btn dark\" onclick=\"location.hash='mail/4'\">${PARTS[3].title} →</button>` : `<button class=\"btn primary\" id=\"f-next\">Mail suivant →</button>`}</div>` : ''}\n      </aside></div>`;\n    wire(el);\n    el.querySelectorAll('.seg[data-err]').forEach(x => x.onclick = e => { if (e.target.closest('.pop')) return; s.open = s.open === x.dataset.id ? null : x.dataset.id; s.msg = null; draw(); });\n    el.querySelectorAll('.seg[data-ok]').forEach(x => x.onclick = () => { x.classList.remove('shake'); void x.offsetWidth; x.classList.add('shake'); });\n    el.querySelectorAll('[data-pick]').forEach(b => b.onclick = e => {\n      e.stopPropagation(); const id = b.dataset.pick;\n      if (b.dataset.right === '1'){ s.st[id] = 'ok'; s.open = null; s.msg = null;\n        const [, li, si] = id.split('-'); const g = li[0]==='h' ? Q.head[+li.slice(1)].segs[+si] : Q.body[+li.slice(1)][+si]; s.log.unshift(g); }\n      else s.msg = \"Relis : cette version garde le même défaut ou en ajoute un. Réessaie.\";\n      draw(); });\n    const nx = $('#f-next'); if (nx) nx.onclick = () => { qi = S.findIndex(x => x.phase !== 3); if (qi < 0) qi = 0; draw(); };\n  };\n  const draw = () => { const s = S[qi]; (s.phase === 1 ? drawSpot : drawFix)(); };\n  draw();\n}\n\nfunction initEntrainer(el){\n  let cur = sessionStorage.getItem('kp-train'); if (!REC[cur]) cur = 'prof';\n  let to = '', subject = '', body = '', sent = null;\n  const norm = t => t.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');\n  const endDot = t => /[.?!…]$/.test(t) ? t : t + '.';\n  const quote = a => a.slice(0,2).map(x => `« ${x} »`).join(', ');\n  const evaluate = () => {\n    const R = REC[cur], X = EXPECT[cur], formal = R.f >= 3, empty = !body.trim();\n    const lines = body.split('\\n').map(l => l.trim()).filter(Boolean);\n    const first = lines[0] || '', last = lines[lines.length-1] || '';\n    const nb = norm(body), nf = norm(first);\n    const paras = body.split(/\\n\\s*\\n/).map(t => t.trim()).filter(Boolean);\n    const words = (body.match(/[\\p{L}\\d'’-]+/gu) || []).length;\n    const TODO = \"À compléter.\";\n    const items = [];\n    const push = (ok, label, hint) => items.push([ok, label, hint]);\n\n    /* 1. Adresse : valide ET conforme à la consigne */\n    const addr = to.trim(), okFmt = /^[^\\s@]+@[^\\s@]+\\.[a-z]{2,}$/i.test(addr);\n    push(okFmt && addr.toLowerCase() === X.email, 'Adresse du destinataire',\n      !addr ? TODO : !okFmt ? 'Format attendu : prenom.nom@domaine.be' : addr.toLowerCase() === X.email ? 'Adresse conforme à la consigne.' : `Ce n'est pas l'adresse indiquée dans la consigne (${X.email}).`);\n\n    /* 2. Objet */\n    const sj = subject.trim(), nsj = norm(sj), sw = sj.split(/\\s+/).filter(Boolean).length;\n    const abbr = (nsj.match(ABBR_G) || []).find(w => !(R.f <= 2 && ABBR_SOFT.has(w))), shout = (sj.match(/\\b[A-ZÀ-Ý]{4,}\\b/) || [])[0];\n    let sh = 'Précis, court et centré sur le sujet.', sok = true;\n    if (!sj){ sok = false; sh = TODO; }\n    else if (sw < 3){ sok = false; sh = 'Trop court : 3 mots minimum pour dire de quoi tu parles.'; }\n    else if (sj.length > 70){ sok = false; sh = 'Trop long : 70 caractères maximum.'; }\n    else if (abbr){ sok = false; sh = `« ${abbr} » est une abréviation : écris le mot en entier${ABBR_MAP[abbr] ? ' (' + ABBR_MAP[abbr] + ')' : ''}.`; }\n    else if (/!/.test(sj) || shout){ sok = false; sh = \"Évite les « ! » et les mots en majuscules dans l'objet.\"; }\n    else if (/^(bonjour|salut|hello|coucou)\\b/.test(nsj)){ sok = false; sh = \"L'objet n'est pas une salutation.\"; }\n    else if (!X.topic.test(nsj)){ sok = false; sh = `L'objet doit citer le sujet (ex. : ${X.topicEx}).`; }\n    push(sok, 'Objet clair', sh);\n\n    /* 3. Formule d'appel */\n    const informalG = /^(salut|coucou|hello|hey|yo|wesh)\\b/.test(nf);\n    const fullMadame = /\\b(madame|monsieur|mesdames|messieurs)\\b/.test(nf);\n    const abbrMme = /\\b(mme|mr|mlle)\\b|(^|\\s)m\\.\\s/.test(nf);\n    let gh = 'Bon ton pour ce destinataire.', gok = true;\n    if (empty){ gok = false; gh = TODO; }\n    else if (!/^(bonjour|bonsoir|madame|monsieur|cher|chere|salut|coucou|hello|hey)\\b/.test(nf)){ gok = false; gh = \"Commence par une salutation (« Bonjour … »).\"; }\n    else if (formal && informalG){ gok = false; gh = `Trop familier pour « ${R.label} ». Essaie « ${R.greet.split(' / ')[0]} »`; }\n    else if (formal && abbrMme){ gok = false; gh = \"Écris « Madame » ou « Monsieur » en toutes lettres.\"; }\n    else if (formal && X.gender && (X.gender === 'f' ? /\\bmonsieur\\b/.test(nf) : /\\bmadame\\b/.test(nf))){ gok = false; gh = `Attention au genre : écris « ${X.gender === 'f' ? 'Madame' : 'Monsieur'} ${X.name[0].toUpperCase()+X.name.slice(1)} ».`; }\n    else if (formal && X.name && !nf.includes(X.name)){ gok = false; gh = fullMadame && !nf.includes(X.name) ? `Utilise le nom de famille du destinataire (${X.name[0].toUpperCase()+X.name.slice(1)}).` : `Adresse-toi à lui/elle par son nom (${X.name[0].toUpperCase()+X.name.slice(1)}).`; }\n    else if (formal && !X.name && !fullMadame){ gok = false; gh = \"Utilise « Madame, Monsieur, » quand tu ne connais pas la personne.\"; }\n    else if (!formal && X.name && !nf.includes(X.name)){ gok = false; gh = `Mets le prénom du destinataire (${X.name[0].toUpperCase()+X.name.slice(1)}).`; }\n    else if (!/[,!]$/.test(first)){ gok = false; gh = \"Termine l'appel par une virgule.\"; }\n    push(gok, \"Formule d'appel\", gh);\n\n    /* 4. Présentation (seulement si la personne ne te connaît pas bien) */\n    const introTxt = norm(lines.slice(1,4).join(' '));\n    const hasIntro = /je suis|je m'appelle|je me presente|eleve|etudiant|stagiaire|classe|\\b\\d+e\\b/.test(introTxt);\n    push(empty ? false : X.intro ? hasIntro : true, 'Présentation',\n      empty ? TODO : !X.intro ? \"Inutile ici : il ou elle te connaît déjà.\" : hasIntro ? 'On sait qui écrit.' : \"Présente-toi en une phrase (nom, classe ou situation).\");\n\n    /* 5. Corps */\n    const bodyParas = paras.filter(t => t !== first && !/^(je vous prie|veuillez|bien cordialement|cordialement)/i.test(t));\n    const longest = Math.max(0, ...paras.map(t => t.split(/\\s+/).length));\n    const minW = formal ? 30 : 12;\n    let bh = `${paras.length} paragraphes, ${words} mots.`, bok = true;\n    if (empty){ bok = false; bh = TODO; }\n    else if (paras.length < 3 && formal){ bok = false; bh = \"Aère ton mail : appel, corps et conclusion séparés par une ligne vide.\"; }\n    else if (paras.length < 2){ bok = false; bh = \"Saute une ligne pour séparer les paragraphes.\"; }\n    else if (words < minW){ bok = false; bh = `Trop court : au moins ${minW} mots pour être clair.`; }\n    else if (longest > 90){ bok = false; bh = \"Un paragraphe est trop long : découpe-le (une idée par paragraphe).\"; }\n    push(bok, 'Corps en paragraphes', bh);\n\n    /* 6. Demande explicite */\n    const okAsk = /\\?|pourriez|pouvez|serait-il|serait il|souhaiterais|aimerais|voudrais|merci de|peux-tu|tu peux|je vous demande|je sollicite|permettre/.test(nb);\n    const askOk = okAsk || (X.ask ? X.ask.test(nb) : false);\n    push(!empty && askOk, X.ask ? 'Message clair' : 'Demande explicite', empty ? TODO : askOk ? 'On sait ce que tu attends.' : (X.askHint || \"Pose ta question : « Serait-il possible de… ? »\"));\n\n    /* 7. Informations concrètes (cohérence avec la consigne) */\n    const miss = X.needs.find(([re]) => !re.test(nb));\n    push(!empty && !miss, 'Informations concrètes', empty ? TODO : miss ? miss[1] : 'Les éléments utiles sont là.');\n\n    /* 8. Formule de politesse : bien placée, avant la signature */\n    const CLOSE = formal ? /cordialement|salutations|agreer|respectueusement|sincerement|bien a vous|restons a votre disposition|dans l'attente/ : /bisous|bises|a plus|a\\+|a bientot|a samedi|a demain|merci|bonne journee|bonne soiree|ciao/;\n    let ci = -1; lines.forEach((l,i) => { if (CLOSE.test(norm(l))) ci = i; });\n    const lastIsClose = CLOSE.test(norm(last));\n    let ph = 'Bien placée, avant la signature.', pok = true;\n    if (empty){ pok = false; ph = TODO; }\n    else if (ci < 0){ pok = false; ph = `Ex. : « ${R.polite.split(' / ')[0]} »`; }\n    else if (lastIsClose && lines.length < 4){ pok = false; ph = \"La formule de politesse doit précéder la signature.\"; }\n    else if (ci < lines.length-4){ pok = false; ph = \"Place la formule de politesse juste avant ta signature.\"; }\n    else if (formal && /(^|\\n)\\s*(salut|coucou|bisous|a plus|a\\+)\\b/.test(norm(lines.slice(1).join('\\n')))){ pok = false; ph = \"Une formule familière gâte la conclusion : garde une seule formule, soutenue.\"; }\n    push(pok, 'Formule de politesse', ph);\n\n    /* 9. Signature */\n    const initials = /^([A-ZÀ-Ý]\\.?\\s?){1,3}$/.test(last);\n    const fullName = /^[A-ZÀ-Ý][\\p{L}'-]+(\\s+[A-ZÀ-Ý][\\p{L}'-]+)+/u.test(last);\n    let sgh = 'On sait qui écrit.', sgok = true;\n    if (empty || lines.length < 2){ sgok = false; sgh = TODO; }\n    else if (CLOSE.test(norm(last)) || /^(salut|coucou|bonne|merci|bisous|cordialement)/.test(norm(last))){ sgok = false; sgh = `« ${last} » n'est pas une signature : termine par ton nom.`; }\n    else if (initials){ sgok = false; sgh = \"Des initiales ne suffisent pas : écris ton prénom (et ton nom).\"; }\n    else if (formal && !fullName){ sgok = false; sgh = \"Termine par ton prénom et ton nom.\"; }\n    else if (!formal && !/^[A-ZÀ-Ý][\\p{L}'-]+/u.test(last)){ sgok = false; sgh = \"Termine par ton prénom, avec une majuscule.\"; }\n    else if (/[,;:]$/.test(last)){ sgok = false; sgh = \"Pas de virgule après la signature.\"; }\n    push(sgok, 'Signature', sgh);\n\n    /* 10. Registre cohérent */\n    const issues = [];\n    const mailBody = lines.slice(1).join('\\n');\n    const nbb = norm(mailBody);\n    if (formal){\n      const tu = nbb.match(/\\b(tu|toi|ton|ta|tes|te|t')\\b/g); if (tu) issues.push(`tutoiement (« ${tu[0]} »)`);\n      const inf = Object.keys(INFORMAL).filter(w => new RegExp('(^|[^a-z])'+norm(w).replace('+','\\\\+')+'([^a-z]|$)').test(nbb));\n      if (inf.length) issues.push(`mot familier ${quote(inf)} → ${INFORMAL[inf[0]]}`);\n      if (/\\p{Extended_Pictographic}/u.test(body)) issues.push(\"emoji\");\n      if (/(^|\\n)\\s*(salut|coucou|hello|hey|bisous)\\b/.test(norm(lines.slice(1).join('\\n')))) issues.push(\"salutation familière au milieu ou en fin de mail\");\n    } else if (R.f <= 2 && /agreer|salutations distinguees|veuillez|je vous prie/.test(nbb)){ issues.push(\"trop solennel pour cette situation\"); }\n    if (formal || R.f === 2){\n      const t = /\\b(tu|toi|ton|ta|tes)\\b/.test(nbb), v = /\\b(vous|votre|vos)\\b/.test(nbb);\n      if (t && v) issues.push(\"tu et vous mélangés\");\n    }\n    const rude = nbb.match(/\\b(idiot|idiote|debile|nul|nulle|merde|con|conne|stupide|arnaque|ferme ta|ta gueule|imbecile)\\b/); if (rude) issues.push(`mot irrespectueux (« ${rude[0]} »)`);\n    if (formal){\n      const bad = []; norm(mailBody).replace(/\\bpas\\b/g, (m, off, str) => { const before = str.slice(Math.max(0, off-28), off); if (!/\\bne\\b|\\bn'|\\bn’/.test(before)) bad.push(m); return m; });\n      if (bad.length && !/\\bne\\b|\\bn'/.test(nbb)) issues.push(\"négation sans « ne » (« je n'ai pas »)\");\n    }\n    if (/!{2,}|\\?{2,}/.test(body) || /\\b[A-ZÀ-Ý]{5,}\\b/.test(mailBody)) issues.push(\"ponctuation ou majuscules criées\");\n    push(!empty && issues.length === 0, 'Registre cohérent', empty ? TODO : issues.length ? endDot(issues.slice(0,2).join(' ; ')) : \"Ton homogène du début à la fin.\");\n\n    /* 11. Ponctuation et majuscules */\n    const content = lines.filter((l,i) => i > 0 && i < lines.length-1 && !CLOSE.test(norm(l)));\n    const noEnd = content.find(l => l.split(/\\s+/).length >= 5 && !/[.?!…]$/.test(l));\n    const noCap = content.find(l => /^[a-zà-ÿ]/.test(l));\n    const dbl = /\\s{2,}/.test(body.replace(/\\n/g,' ').replace(/\\s+\\n/g,' ')) && /\\S {2,}\\S/.test(body);\n    const rep = (nb.match(/\\b([a-zàâçéèêëîïôûù']{2,})\\s+\\1\\b/) || [])[1];\n    const comma = /,[^\\s\\d]/.test(body.replace(/https?:\\/\\/\\S+/g,'').replace(/\\S+@\\S+/g,''));\n    let ph2 = 'Phrases bien construites.', ok2 = true;\n    if (empty){ ok2 = false; ph2 = TODO; }\n    else if (noCap){ ok2 = false; ph2 = `Commence chaque phrase par une majuscule (« ${noCap.slice(0,24)}… »).`; }\n    else if (noEnd){ ok2 = false; ph2 = `Termine tes phrases par un point (« ${noEnd.slice(0,24)}… »).`; }\n    else if (rep){ ok2 = false; ph2 = `Mot répété : « ${rep} ${rep} ».`; }\n    else if (dbl){ ok2 = false; ph2 = \"Double espace repéré : un seul suffit.\"; }\n    else if (comma){ ok2 = false; ph2 = \"Mets une espace après chaque virgule.\"; }\n    push(ok2, 'Ponctuation et majuscules', ph2);\n\n    /* 12. Ordre logique : appel → présentation → demande → politesse → signature */\n    const nline = lines.map(l => norm(l.replace(/’/g,\"'\")));\n    const isClose = i => CLOSE.test(nline[i]);\n    const askRe = /\\?|pourriez|pouvez|serait-il|serait il|souhaiterais|aimerais|voudrais|peux-tu|tu peux|je vous demande|je sollicite|permettre|est-ce que/;\n    const askIdx = (() => { let k = -1; nline.forEach((l,i) => { if (i > 0 && !isClose(i) && askRe.test(l)) k = i; }); return k; })();\n    const introIdx = nline.findIndex((l,i) => i > 0 && /je suis|je m'appelle|je me presente|eleve|etudiant|stagiaire/.test(l));\n    const closeIdx = (() => { let k = -1; nline.forEach((l,i) => { if (i > 0 && isClose(i)) k = i; }); return k; })();\n    const startsClose = lines.length > 1 && (CLOSE.test(nf) || /^(je vous prie|veuillez|cordialement|bien cordialement)/.test(nf));\n    const lastLong = last.split(/\\s+/).length > 4 && !fullName;\n    let oh = \"Le mail suit un ordre naturel.\", ook = true;\n    if (empty){ ook = false; oh = TODO; }\n    else if (startsClose){ ook = false; oh = \"La formule de politesse est au début : un mail commence par l'appel (« Bonjour… »).\"; }\n    else if (lastLong){ ook = false; oh = \"Le mail doit se terminer par ta signature, pas par une phrase.\"; }\n    else if (closeIdx > -1 && askIdx > closeIdx){ ook = false; oh = \"La demande arrive après la formule de politesse : remets-la avant la conclusion.\"; }\n    else if (introIdx > -1 && askIdx > -1 && askIdx < introIdx){ ook = false; oh = \"Présente-toi avant de formuler ta demande.\"; }\n    else if (introIdx > -1 && closeIdx > -1 && introIdx > closeIdx){ ook = false; oh = \"La présentation arrive après la conclusion : remets les paragraphes dans l'ordre.\"; }\n    else if (/^(salut|bonjour|bonsoir|coucou|hello|madame|monsieur)\\b/.test(nline[lines.length-1] || '') && lines.length > 1){ ook = false; oh = \"Le mail se termine par une salutation d'ouverture : vérifie l'ordre des paragraphes.\"; }\n    push(ook, 'Ordre logique', oh);\n\n    /* 13. Mots compréhensibles : abréviations, charabia, mélange de langues, phrases sans sens */\n    const q = norm(body.replace(/’/g,\"'\")), qw = q.match(/[a-z0-9]+(?:'[a-z0-9]+)*/g) || [];\n    const orig = {}; (body.toLowerCase().match(/[\\p{L}\\d]+(?:['’][\\p{L}\\d]+)*/gu) || []).forEach(w => { const k = norm(w.replace(/’/g,\"'\")); if (!orig[k]) orig[k] = w; });\n    const show = w => orig[w] || w;\n    const wi = [];\n    const abbrs = [...new Set((q.match(ABBR_G) || []).filter(w => !(R.f <= 2 && ABBR_SOFT.has(w))))];\n    if (abbrs.length) wi.push(`mot abrégé ${abbrs.slice(0,2).map(w => `« ${w} »${ABBR_MAP[w] ? ' → ' + ABBR_MAP[w] : ''}`).join(', ')}`);\n    if (/\\bpresse\\b/.test(q) && /presentation/.test(X.topic.source)) wi.push(\"« presse » : voulais-tu écrire « présentation » ?\");\n    const gib = [...new Set(qw.filter(w => {\n      const a = w.replace(/\\d|'/g, ''); if (a.length < 2) return false;\n      if (/^\\d+(e|er|eme|h\\d*|x|%)?$/.test(w) || /^\\d+(e|er|eme|h\\d*)$/.test(w)) return false;\n      if (/^[a-z]\\d|\\d[a-z]/.test(w) && !/^\\d+(e|er|eme|h\\d*|x)$/.test(w)) return true;\n      return (!/[aeiouy]/.test(a) && a.length >= 3 && !ABBR_MAP[a] && !/^(mr|mme|mlle|dr|st|ste|cv|pdf|sms|tv|web|www|sncb|cpas)$/.test(a)) || /(.)\\1{3,}/.test(a) || /[bcdfghjklmnpqrstvwxz]{5,}/.test(a)\n        || /qwer|azer|wxcv|qsdf|asdf|sdfg|dfgh|poiu|uiop|hjkl|zxcv|ghjk/.test(a) || a.length >= 22 || (a.length >= 6 && /^(.{2,4}?)\\1{2,}$/.test(a)); }))];\n    if (gib.length) wi.push(`« ${show(gib[0])} » n'est pas un mot compréhensible`);\n    const cnt = {}; qw.filter(w => w.length >= 4 && !FUNC.test(w)).forEach(w => cnt[w] = (cnt[w] || 0) + 1);\n    const rep2 = Object.keys(cnt).find(w => cnt[w] >= 4); if (rep2) wi.push(`« ${show(rep2)} » est répété ${cnt[rep2]} fois`);\n    if (ENGLISH.test(q)) wi.push(\"mélange de langues (écris tout en français)\");\n    const sens = content.flatMap(l => l.split(/(?<=[.!?…])\\s+/)).filter(sn => (sn.match(/[\\p{L}'’-]+/gu) || []).length >= 5)\n      .find(sn => { const n = norm(sn.replace(/’/g,\"'\")); return !(FUNC.test(n) && (AUX.test(n) || VERBSUF.test(n))); });\n    if (sens) wi.push(`« ${sens.split(/\\s+/).slice(0,5).join(' ')}… » : phrase sans structure ou sans sens`);\n    push(!empty && wi.length === 0, 'Mots compréhensibles', empty ? TODO : wi.length ? endDot(wi.slice(0,2).join(' ; ')) : 'Des mots clairs, des phrases construites.');\n\n    /* 14. Fond cohérent : le message parle bien du sujet, sans répétition ni recopie */\n    const fi = [];\n    if (!(X.bodyTopic || X.topic).test(q)) fi.push(`le message ne parle pas du sujet (ex. : ${X.topicEx})`);\n    const sh5 = t => { const w = t.match(/[a-z0-9]+/g) || [], o = new Set(); for (let i = 0; i + 12 <= w.length; i++) o.add(w.slice(i, i+12).join(' ')); return o; };\n    const sc = sh5(norm(R.scenario)); if ([...sh5(q)].some(x => sc.has(x))) fi.push(\"tu as recopié la consigne : écris avec tes propres mots\");\n    const sentences = q.split(/[.!?\\n]+/).map(t => t.trim()).filter(t => t.split(/\\s+/).length >= 4);\n    if (new Set(sentences).size < sentences.length) fi.push(\"une phrase est écrite deux fois\");\n    if (/lorem ipsum|test test|azerty|blabla/.test(q)) fi.push(\"texte de remplissage\");\n    const uniq = new Set(qw.filter(w => !FUNC.test(w))).size; if (qw.length >= 25 && uniq / qw.length < 0.3) fi.push(\"trop de répétitions\");\n    push(!empty && fi.length === 0, 'Fond cohérent', empty ? TODO : fi.length ? endDot(fi.slice(0,2).join(' ; ')) : 'Le message correspond bien à la situation.');\n    return items;\n  };\n  el.innerHTML = `<div class=\"chips\" id=\"t-chips\"></div>\n    <div class=\"train\">\n      <div style=\"display:grid;gap:14px;min-width:0\">\n        <div class=\"scn\" id=\"t-scn\"></div>\n        <div class=\"mailwin\">\n          <label class=\"field\"><span class=\"l\">À</span><input id=\"t-to\" placeholder=\"prenom.nom@domaine.be\"></label>\n          <label class=\"field\"><span class=\"l\">Objet</span><input id=\"t-subj\" placeholder=\"De quoi parles-tu ?\"></label>\n          <textarea id=\"t-body\" placeholder=\"Bonjour…\"></textarea>\n        </div>\n        <div class=\"btnrow\" style=\"align-items:center\"><button class=\"btn cta\" id=\"t-send\">Envoyer ✉️</button><button class=\"btn\" id=\"t-reset\">Effacer</button><span class=\"msg\" id=\"t-msg\"></span></div>\n      </div>\n      <aside class=\"checks\" id=\"t-checks\"></aside>\n    </div>`;\n  const live = () => {\n    const list = evaluate(), n = list.filter(c => c[0]).length, N = list.length;\n    $('#t-checks').innerHTML = `<div class=\"top\"><b>${n}/${N}</b><span style=\"font-size:13px;color:var(--muted)\">Analyse du mail</span></div>\n      <div class=\"meter ${n===N?'full':''}\"><i style=\"width:${n/N*100}%\"></i></div>\n      ${list.map(([ok,l,h],i) => `<div class=\"ck ${ok?'ok':''}\"><span class=\"m\">${ok?'✓':i+1}</span><div>${l}<small>${h}</small></div></div>`).join('')}`;\n    $('#t-msg').textContent = sent === 'ok' ? `✓ Mail validé, ${N}/${N}. Bravo !` : sent === 'ko' ? `Encore ${N-n} point${N-n>1?'s':''} à corriger avant d'envoyer.` : '';\n    $('#t-msg').style.color = sent === 'ok' ? 'var(--success)' : 'var(--accent)';\n    return n;\n  };\n  const paint = () => {\n    const chip = k => `<button class=\"chip ${k===cur?'on':''}\" data-k=\"${k}\">${REC[k].emoji ? REC[k].emoji+' ' : ''}${REC[k].label}</button>`;\n    $('#t-chips').innerHTML = CORE.map(chip).join('') + `<span class=\"chipsep\">Pour s'amuser</span>` + FUN.map(chip).join('');\n    $('#t-chips').querySelectorAll('.chip').forEach(c => c.onclick = () => { cur = c.dataset.k; sent = null; paint(); });\n    $('#t-scn').textContent = REC[cur].scenario; live();\n  };\n  $('#t-to').oninput = e => { to = e.target.value; sent = null; live(); };\n  $('#t-subj').oninput = e => { subject = e.target.value; sent = null; live(); };\n  $('#t-body').oninput = e => { body = e.target.value; sent = null; live(); };\n  $('#t-reset').onclick = () => { to = subject = body = ''; sent = null; $('#t-to').value = $('#t-subj').value = $('#t-body').value = ''; live(); };\n  $('#t-send').onclick = () => { const n = live(), N = evaluate().length; sent = n === N ? 'ok' : 'ko'; live(); if (n === N) completePart('entrainer'); };\n  paint();\n}\n\nroute();\n";
